import { get, handleApiError } from '@helpers/httpClient';

import { mapHikingNotes } from '../@mappers/hikingNotes.mapper';
import { IHikingNotesDTO } from '../@types/DTO/hikingNotes.dto.types';
export const getHikingNotes = async (id_hiking: number) => {
  const res = await get('/ajax/hiking/notes/list.php', { id_hiking }).then<IHikingNotesDTO[]>(
    handleApiError,
  );

  return res.map(mapHikingNotes);
};
